import{_ as e,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Node(TS) · 02 核心能力","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/backend/nodejs/02-core.md","filePath":"tech-system/backend/nodejs/02-core.md"}'),s={name:"tech-system/backend/nodejs/02-core.md"};function i(o,t,n,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="node-ts-·-02-核心能力" tabindex="-1">Node(TS) · 02 核心能力 <a class="header-anchor" href="#node-ts-·-02-核心能力" aria-label="Permalink to “Node(TS) · 02 核心能力”">​</a></h1><blockquote><p>真正不同：事件循环、非阻塞 I/O、单线程约束、与 Java 的边界。</p></blockquote><h2 id="_1-事件循环与非阻塞-i-o" tabindex="-1">1. 事件循环与非阻塞 I/O <a class="header-anchor" href="#_1-事件循环与非阻塞-i-o" aria-label="Permalink to “1. 事件循环与非阻塞 I/O”">​</a></h2><p>Node 强在 <strong>等高连接、多等待</strong>，弱在 <strong>算得凶</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请求进来 → 注册 IO → 事件循环继续接别的请求</span></span>
<span class="line"><span>         ← IO 完成回调/Promise 续上</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>CPU 重活（大 JSON 狂转、图片重处理、加密扫目录）会 <strong>堵住整进程</strong></li><li>解决：worker 线程、子进程、或把重活丢给 Java/Python/专用服务</li></ul><p>一句话：<strong>Node 强在等 I/O，弱在算得凶。</strong></p><hr><h2 id="_2-typescript-在服务端的意义" tabindex="-1">2. TypeScript 在服务端的意义 <a class="header-anchor" href="#_2-typescript-在服务端的意义" aria-label="Permalink to “2. TypeScript 在服务端的意义”">​</a></h2><table tabindex="0"><thead><tr><th>收益</th><th>说明</th></tr></thead><tbody><tr><td>协作与重构安全带</td><td>改字段名有编译器挡一程</td></tr><tr><td>与前端同构</td><td>少写一份「口头约定」</td></tr><tr><td>文档感</td><td>类型即注释（仍要补充运行时校验）</td></tr></tbody></table><p>局限：</p><ul><li>编译通过 ≠ 运行正确（断言 <code>as</code> 可以骗人）</li><li>性能与资源管理仍是运行时问题，类型帮不上</li></ul><hr><h2 id="_3-适合什么-不适合什么" tabindex="-1">3. 适合什么 / 不适合什么 <a class="header-anchor" href="#_3-适合什么-不适合什么" aria-label="Permalink to “3. 适合什么 / 不适合什么”">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>不适合</th></tr></thead><tbody><tr><td>BFF、聚合接口、WebSocket</td><td>重 CPU、复杂强事务核心域（优先 Java）</td></tr><tr><td>Electron 本地服务、前端同构工具链</td><td>「为了用 Node 而用 Node」重写整套 ERP</td></tr><tr><td>实时通知、轻网关</td><td>无类型纪律的大团队长期硬扛中大型域</td></tr><tr><td>设备旁路、本地文件/串口桥</td><td>强一致库存核心（可做前端，权威在 Java）</td></tr></tbody></table><hr><h2 id="_4-我为什么用-node-ts" tabindex="-1">4. 我为什么用 Node(TS) <a class="header-anchor" href="#_4-我为什么用-node-ts" aria-label="Permalink to “4. 我为什么用 Node(TS)”">​</a></h2><ol><li>前端 Vue、桌面 Electron 已在栈内，本地服务与 BFF 同语言最省事</li><li>和 Java 分工：Java 管域与库表，Node 管靠近端的聚合与实时</li><li>不为炫技上 Nest 全家桶；场景简单就 Express/Fastify + TS</li></ol><h3 id="和-mes-桌面的关系" tabindex="-1">和 MES / 桌面的关系 <a class="header-anchor" href="#和-mes-桌面的关系" aria-label="Permalink to “和 MES / 桌面的关系”">​</a></h3><p>上位机（Electron）需要本地进程：采数、转协议、落临时文件——Node 很合适；<br> 工单权威状态、追溯查询仍回 Java API。</p><p>下一篇：<a href="./03-frameworks.html">03 框架与生态</a></p>`,21)])])}const _=e(s,[["render",i]]);export{b as __pageData,_ as default};
